using System.Text.RegularExpressions;

public static class Validator
{
    // BUG: constructs a new Regex INSIDE the loop - re-parses the same fixed
    // pattern on every call, unusably slow for large inputs.
    public static int CountValid(string[] lines)
    {
        int count = 0;
        foreach (var line in lines)
        {
            var re = new Regex(@"^user-\d+@example\.com$");
            if (re.IsMatch(line))
            {
                count++;
            }
        }
        return count;
    }
}

