using System;
using System.Diagnostics;
using Xunit;

public class ValidatorTests
{
    [Fact]
    public void CountsValidLines()
    {
        var lines = new[] { "user-1@example.com", "nope", "user-42@example.com", "user-x@example.com" };
        Assert.Equal(2, Validator.CountValid(lines));
    }

    [Fact]
    public void EmptyIsZero()
    {
        Assert.Equal(0, Validator.CountValid(Array.Empty<string>()));
    }

    [Fact]
    public void PerformanceLargeInput()
    {
        int n = 300_000;
        var lines = new string[n];
        int expected = 0;
        for (int i = 0; i < n; i++)
        {
            if (i % 3 == 0)
            {
                lines[i] = $"user-{i}@example.com";
                expected++;
            }
            else
            {
                lines[i] = $"nope-{i}";
            }
        }

        var sw = Stopwatch.StartNew();
        var got = Validator.CountValid(lines);
        sw.Stop();

        Assert.Equal(expected, got);
        Assert.True(
            sw.ElapsedMilliseconds < 800,
            $"CountValid took {sw.ElapsedMilliseconds}ms for {n} lines; expected a Regex compiled once, not per call");
    }
}

