using System.Text.RegularExpressions;

public static class Validator
{
    // Correct output but still constructs a Regex per call via a helper -
    // the parse cost is paid every iteration either way.
    private static Regex MakePattern() => new Regex(@"^user-\d+@example\.com$");

    public static int CountValid(string[] lines)
    {
        int count = 0;
        foreach (var line in lines)
        {
            var re = MakePattern();
            if (re.IsMatch(line))
            {
                count++;
            }
        }
        return count;
    }
}
